ALTER TABLE life_festival_plans ADD COLUMN appointment_id INTEGER REFERENCES planner_appointments(id) ON DELETE SET NULL;
ALTER TABLE life_festival_items ADD COLUMN actual_amount REAL NOT NULL DEFAULT 0 CHECK(actual_amount>=0);
ALTER TABLE life_festival_items ADD COLUMN expense_id INTEGER REFERENCES expenses(id) ON DELETE SET NULL;
ALTER TABLE life_metals ADD COLUMN purity_unit TEXT NOT NULL DEFAULT 'percent';
ALTER TABLE life_metal_prices ADD COLUMN purity REAL NOT NULL DEFAULT 100;
ALTER TABLE life_deposits ADD COLUMN compounding TEXT NOT NULL DEFAULT 'simple';
ALTER TABLE life_deposits ADD COLUMN tax_percent REAL NOT NULL DEFAULT 0;
ALTER TABLE life_deposits ADD COLUMN fees REAL NOT NULL DEFAULT 0;
ALTER TABLE life_deposits ADD COLUMN source TEXT NOT NULL DEFAULT '';
ALTER TABLE life_groceries ADD COLUMN actual_cost REAL NOT NULL DEFAULT 0;
ALTER TABLE life_groceries ADD COLUMN expense_id INTEGER REFERENCES expenses(id) ON DELETE SET NULL;
ALTER TABLE life_followups ADD COLUMN interval_days INTEGER NOT NULL DEFAULT 0;
CREATE TABLE life_archives(entity TEXT NOT NULL,row_id INTEGER NOT NULL,PRIMARY KEY(entity,row_id));
CREATE TABLE life_seettu_members(id INTEGER PRIMARY KEY,seettu_id INTEGER NOT NULL REFERENCES life_seettu(id) ON DELETE RESTRICT,name TEXT NOT NULL,round_no INTEGER NOT NULL,UNIQUE(seettu_id,round_no));
CREATE TABLE life_seettu_member_payments(id INTEGER PRIMARY KEY,member_id INTEGER NOT NULL REFERENCES life_seettu_members(id) ON DELETE RESTRICT,round_no INTEGER NOT NULL,amount REAL NOT NULL CHECK(amount>0),paid_on TEXT NOT NULL,UNIQUE(member_id,round_no));
CREATE TABLE life_seettu_payouts(id INTEGER PRIMARY KEY,seettu_id INTEGER NOT NULL REFERENCES life_seettu(id) ON DELETE RESTRICT,member_id INTEGER NOT NULL REFERENCES life_seettu_members(id) ON DELETE RESTRICT,round_no INTEGER NOT NULL,amount REAL NOT NULL CHECK(amount>0),received_on TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',UNIQUE(seettu_id,round_no));
CREATE TABLE life_fx_transactions(id INTEGER PRIMARY KEY,rate_id INTEGER NOT NULL REFERENCES life_fx_rates(id) ON DELETE RESTRICT,code TEXT NOT NULL,amount REAL NOT NULL,rate_lkr REAL NOT NULL,lkr_amount REAL NOT NULL,date TEXT NOT NULL,direction TEXT NOT NULL,source TEXT NOT NULL);
CREATE TABLE life_meal_ingredients(id INTEGER PRIMARY KEY,meal_id INTEGER NOT NULL REFERENCES life_meals(id) ON DELETE RESTRICT,item TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,estimated_cost REAL NOT NULL DEFAULT 0,grocery_id INTEGER REFERENCES life_groceries(id) ON DELETE SET NULL);
CREATE TABLE life_food_budgets(id INTEGER PRIMARY KEY,month TEXT NOT NULL UNIQUE,budget REAL NOT NULL CHECK(budget>=0));
CREATE TABLE life_loan_scenarios(id INTEGER PRIMARY KEY,title TEXT NOT NULL,principal REAL NOT NULL,annual_rate REAL NOT NULL,months INTEGER NOT NULL,early_month INTEGER NOT NULL DEFAULT 0,early_amount REAL NOT NULL DEFAULT 0,settlement_fee REAL NOT NULL DEFAULT 0);
CREATE TABLE life_followup_history(id INTEGER PRIMARY KEY,followup_id INTEGER NOT NULL REFERENCES life_followups(id),due_on TEXT NOT NULL,completed_on TEXT NOT NULL,UNIQUE(followup_id,due_on));
CREATE TABLE life_health_completions(id INTEGER PRIMARY KEY,reminder_id INTEGER NOT NULL REFERENCES life_health_reminders(id),due_on TEXT NOT NULL,completed_on TEXT NOT NULL,UNIQUE(reminder_id,due_on));
